insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$joinville$q$, $q$https://diariomunicipal.sc.gov.br/atos/3737444 (Decreto 10.251/2001); https://diariomunicipal.sc.gov.br/atos/3738958 (Decreto 12.512/2005)$q$, $q$Ato oficial de Joinville: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Cópia dos decretos no DOM/SC é de acervo (não publicação oficial), por isso confiança média. Vigência real e sinalização no terreno não confirmadas (órgão CONURB citado no ato; hoje o trânsito é do DETRANS). O perímetro ampliado em 2005 inclui a Rua Marechal Deodoro e a Rua Tijucas, que não constam da lista de vias liberadas (art. 6º, §1º): o recuo de 20 m da camada as deixa livres. Joinville não define VUC nos atos lidos.$q$);
